const PROJECTS = [
  { project_id: '964775386a3ce03ecca883.03770715', name: 'Realchecker (FE)', role: 'source' },
  { project_id: '852017176a3ce11141ecd5.60405885', name: 'Realchecker (BE)', role: 'source' },
  { project_id: '14240418673f52ae29a007.74392007', name: 'Mobitrace', role: 'target' },
  { project_id: '9274956467e3e224807498.79791832', name: 'Mobitrace - backend/emails', role: 'target' },
  { project_id: '901014606819db6d0bc999.26230201', name: 'Mobitrace - html/legal pages', role: 'target' }
];
const out = [];
for (const p of PROJECTS) { out.push({ json: p }); }
return out;

const INCLUDE_NEAR = true;
const SKIP_REVIEWED = true;
const metas = $('Build Key Requests').all();
const res = $input.all();
const src = [];
const tgt = [];
const failed = [];

function kname(k) {
  if (k.key_name && typeof k.key_name === 'object') { return k.key_name.web || k.key_name.other || k.key_name.ios || k.key_name.android; }
  return k.key_name;
}
function norm(s) { if (typeof s !== 'string') { return ''; } return s.replace(/\s+/g, ' ').trim().toLowerCase(); }

for (let i = 0; i < res.length; i++) {
  const meta = metas[i] ? metas[i].json : {};
  const r = res[i].json || {};
  if (r.statusCode !== 200) { failed.push(meta.project_name + ' -> ' + r.statusCode); continue; }
  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  for (const k of keys) {
    let en = null;
    let el = null;
    let hasEl = false;
    let elReviewed = false;
    for (const t of (k.translations || [])) {
      const iso = String(t.language_iso || '').toLowerCase();
      if (iso === 'en') { en = t.translation; }
      if (iso === 'el') { el = t.translation; hasEl = true; elReviewed = t.is_reviewed === true; }
    }
    const row = { project_id: meta.project_id, project_name: meta.project_name, key_id: k.key_id, key_name: kname(k), is_archived: k.is_archived === true, en: en, el: el, has_el: hasEl, el_reviewed: elReviewed };
    if (meta.role === 'source') { src.push(row); } else { tgt.push(row); }
  }
}

const exactIdx = {};
const normIdx = {};
for (const t of tgt) {
  if (typeof t.en !== 'string' || t.en === '') { continue; }
  const ek = 'E' + t.en;
  if (!exactIdx[ek]) { exactIdx[ek] = []; }
  exactIdx[ek].push(t);
  const nk = 'N' + norm(t.en);
  if (!normIdx[nk]) { normIdx[nk] = []; }
  normIdx[nk].push(t);
}

const plan = {};
for (const s of src) {
  if (typeof s.en !== 'string' || s.en === '') { continue; }
  let hits = exactIdx['E' + s.en] || [];
  let kind = 'exact';
  if (hits.length === 0) {
    if (!INCLUDE_NEAR) { continue; }
    hits = normIdx['N' + norm(s.en)] || [];
    kind = 'near';
  }
  for (const t of hits) {
    const pk = t.project_id + '::' + t.key_id;
    if (!plan[pk]) { plan[pk] = { t: t, cands: [] }; }
    plan[pk].cands.push({ kind: kind, s: s });
  }
}

const writes = [];
const skipped = [];
for (const pk in plan) {
  const t = plan[pk].t;
  const cands = plan[pk].cands.slice();
  cands.sort(function (a, b) {
    const ka = (a.kind === 'exact' ? 0 : 1) * 10 + (a.s.key_name === t.key_name ? 0 : 1);
    const kb = (b.kind === 'exact' ? 0 : 1) * 10 + (b.s.key_name === t.key_name ? 0 : 1);
    return ka - kb;
  });
  const chosen = cands[0];
  const newEl = chosen.s.el;
  let reason = null;
  if (t.is_archived || !t.has_el) { reason = 'archived or no Greek'; }
  else if (t.el === newEl) { reason = 'already identical'; }
  else if (SKIP_REVIEWED && t.el_reviewed) { reason = 'reviewed in Mobitrace'; }
  else if (typeof newEl !== 'string' || newEl === '') { reason = 'source Greek empty'; }
  if (reason) { skipped.push({ project: t.project_name, key: t.key_name, key_id: t.key_id, reason: reason }); continue; }
  writes.push({ project_id: t.project_id, project_name: t.project_name, key_id: t.key_id, key_name: t.key_name, kind: chosen.kind, old_el: t.el, new_el: newEl, rc_key: chosen.s.project_name + ' / ' + chosen.s.key_name });
}

const byProject = {};
for (const w of writes) { if (!byProject[w.project_id]) { byProject[w.project_id] = []; } byProject[w.project_id].push(w); }
const out = [];
for (const pid in byProject) {
  const list = byProject[pid];
  for (let i = 0; i < list.length; i += 50) {
    const chunk = list.slice(i, i + 50);
    const keys = [];
    for (const w of chunk) { keys.push({ key_id: w.key_id, translations: [{ language_iso: 'el', translation: w.new_el }] }); }
    out.push({ json: { project_id: pid, batch: i / 50, count: keys.length, rows: chunk, payload: { keys: keys } } });
  }
}
if (out.length) { out[0].json.summary = { src_count: src.length, tgt_count: tgt.length, failed: failed, write_count: writes.length, skip_count: skipped.length, skipped: skipped }; }
return out;

const metas = $('Build Write Batches').all();
const res = $input.all();
const statuses = {};
const errors = [];
const updated = [];
const rows = [];
let attempted = 0;
for (let i = 0; i < res.length; i++) {
  const meta = metas[i] ? metas[i].json : {};
  const r = res[i].json || {};
  statuses[String(r.statusCode)] = (statuses[String(r.statusCode)] || 0) + 1;
  attempted += meta.count || 0;
  for (const w of (meta.rows || [])) { rows.push(w); }
  const body = r.body || {};
  if (r.statusCode !== 200) { errors.push({ project: meta.project_id, batch: meta.batch, status: r.statusCode, body: JSON.stringify(body).slice(0, 500) }); continue; }
  for (const e of (body.errors || [])) { errors.push({ project: meta.project_id, batch: meta.batch, err: JSON.stringify(e).slice(0, 300) }); }
  for (const k of (body.keys || [])) { updated.push(k.key_id); }
}
const summary = metas[0] ? metas[0].json.summary : null;
return [{ json: { attempted: attempted, statuses: statuses, updated_key_count: updated.length, error_count: errors.length, errors: errors, plan_summary: summary, written_rows: rows, updated_key_ids: updated } }];
